<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Copy, Download, ArrowUpRight } from 'lucide-vue-next'
import { products } from '../data/site'
import { useLocale } from '../composables/useLocale'
import PageHero from '../components/PageHero.vue'
import StoreLinks from '../components/StoreLinks.vue'
const { t, tx } = useLocale(), route = useRoute()
const name = ref(''), email = ref(''), company = ref(''), quantity = ref(''), message = ref(''), interest = ref(''), consent = ref(false)
const ready = ref(false), copyState = ref(''), summary = ref(null), firstField = ref(null)
watch(() => route.query.interest, value => { if (['0', '1', '2', '3'].includes(value)) interest.value = value }, { immediate: true })
const selectedProduct = computed(() => products.find(p => p.handle === route.query.product))
const draft = computed(() => [t('contact.draft'), '', ...[['name', name.value], ['email', email.value], ['company', company.value], ['interest', t('contact.types')[Number(interest.value)]], ['quantity', quantity.value], ['message', message.value]].map(([key, value]) => `${t(`contact.${key}`)}: ${value || t('contact.empty')}`), ...(selectedProduct.value ? [`${t('common.collection')}: ${tx(selectedProduct.value.name)}`] : [])].join('\n'))
async function prepare() { ready.value = true; copyState.value = ''; await nextTick(); summary.value?.focus() }
async function edit() { ready.value = false; await nextTick(); firstField.value?.focus() }
async function copy() { try { await navigator.clipboard.writeText(draft.value); copyState.value = 'copied' } catch { copyState.value = 'copyError' } }
function download() { const url = URL.createObjectURL(new Blob([draft.value], { type: 'text/plain;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'DLIM-HOME-enquiry.txt'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
</script>
<template><main id="main-content"><PageHero page="contact" image="dining"><a href="#enquiry" class="button button-dark">{{ t('common.enquire') }}</a></PageHero><section id="stores" class="section-space section-muted"><div class="container two-columns"><div><p class="eyebrow">{{ t('common.store') }}</p><h2>{{ t('contact.consumerTitle') }}</h2><p class="lead">{{ t('contact.consumerCopy') }}</p><StoreLinks /></div><div class="editorial-card"><p class="eyebrow">DLIM HOME · B2B</p><h2>{{ t('contact.tradeTitle') }}</h2><p class="lead">{{ t('contact.tradeCopy') }}</p><a href="#enquiry" class="text-link">{{ t('common.enquire') }}<ArrowUpRight :size="18" /></a></div></div></section>
<section id="enquiry" class="section-space"><div class="container enquiry-layout"><div class="enquiry-intro"><p class="eyebrow">{{ t('contact.label') }}</p><h2>{{ t('contact.formTitle') }}</h2><p class="lead">{{ t('contact.formCopy') }}</p><p v-if="selectedProduct" class="selected-product">{{ t('common.collection') }}<strong>{{ tx(selectedProduct.name) }}</strong></p><img src="/images/ceramics/craft.jpg" :alt="t('common.imageNote')" loading="lazy" width="480" height="320" /></div>
<form v-if="!ready" class="enquiry-form" @submit.prevent="prepare"><div class="form-grid"><label>{{ t('contact.name') }}<input ref="firstField" v-model="name" name="name" autocomplete="name" required maxlength="100" /></label><label>{{ t('contact.email') }}<input v-model="email" name="email" type="email" autocomplete="email" required maxlength="254" /></label><label>{{ t('contact.company') }} <span>{{ t('contact.optional') }}</span><input v-model="company" name="company" autocomplete="organization" maxlength="150" /></label><label>{{ t('contact.interest') }}<select v-model="interest" name="interest" required><option value="" disabled>{{ t('contact.select') }}</option><option v-for="(type, i) in t('contact.types')" :key="i" :value="String(i)">{{ type }}</option></select></label><label class="full-field">{{ t('contact.quantity') }} <span>{{ t('contact.optional') }}</span><input v-model="quantity" name="quantity" :placeholder="t('contact.quantityPlaceholder')" maxlength="150" /></label><label class="full-field">{{ t('contact.message') }}<textarea v-model="message" name="message" rows="6" required maxlength="5000" :placeholder="t('contact.messagePlaceholder')" /></label></div><label class="consent-label"><input v-model="consent" type="checkbox" required /><span>{{ t('contact.consent') }}</span></label><button class="button button-dark" type="submit">{{ t('contact.prepare') }}<ArrowUpRight :size="18" /></button></form>
<div v-else class="enquiry-result"><h3 ref="summary" tabindex="-1">{{ t('contact.ready') }}</h3><p class="lead">{{ t('contact.readyCopy') }}</p><label for="enquiry-draft" class="sr-only">{{ t('contact.draft') }}</label><textarea id="enquiry-draft" :value="draft" readonly rows="14" /><div class="button-row"><button class="button button-dark" type="button" @click="copy"><Copy :size="16" />{{ t('contact.copy') }}</button><button class="button store-button" type="button" @click="download"><Download :size="16" />{{ t('contact.download') }}</button><button class="text-button" type="button" @click="edit">{{ t('contact.edit') }}</button></div><p v-if="copyState" role="status" class="fine-print">{{ t(`contact.${copyState}`) }}</p><StoreLinks /></div>
</div></section></main></template>